/* FOLIO — dependency-free public journal and publishing workspace.
 * All writes use the same revision-guarded operations as the CLI and MCP server.
 * Keyboard interaction references are documented in docs/INSPIRATION.md. */
(() => {
  'use strict';
  const I18n = window.FolioI18n;
  const app = document.getElementById('app');
  const $ = (s, root = document) => root.querySelector(s);
  const $$ = (s, root = document) => [...root.querySelectorAll(s)];
  const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const url = v => encodeURIComponent(String(v ?? ''));
  const state = { site: null, posts: [], editor: null, dirty: false, busy: false, token: sessionStorage.getItem('folio.token') || '', render: 0, listFilter: 'all', listQuery: '', viewMode: 'write' };
  const icons = {
    arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>', northeast:'<path d="M6 18 18 6M6 6h12v12"/>', search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>', close:'<path d="m6 6 12 12M6 18 18 6"/>', menu:'<path d="M4 7h16M4 12h16M4 17h16"/>', plus:'<path d="M12 5v14M5 12h14"/>', back:'<path d="M19 12H5m6-6-6 6 6 6"/>', edit:'<path d="m15 5 4 4M5 19l4-1L20 7a2.8 2.8 0 0 0-4-4L5 14z"/>', posts:'<rect x="5" y="3" width="14" height="18" rx="1"/><path d="M9 8h6M9 12h6M9 16h4"/>', image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1"/><path d="m3 17 5-5 4 4 4-7 5 8"/>', settings:'<path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z"/><path d="m10 3-.5 3-2.5 1-2.5-1.2-2 3.5L5 11v3l-2.5 1.5 2 3.5L7 18l2.5 1 .5 3h4l.5-3 2.5-1 2.5 1 2-3.5L19 14v-3l2.5-1.7-2-3.5L17 7l-2.5-1L14 3z" transform="translate(0 -1) scale(.96)"/>', terminal:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="m7 9 3 3-3 3M13 15h4"/>', eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>', download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>', upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4"/>', logout:'<path d="M10 3H4v18h6M9 12h12m-4-4 4 4-4 4"/>', link:'<path d="m10 14 4-4M8 16l-1 1a4.2 4.2 0 0 1-6-6l5-5a4.2 4.2 0 0 1 6 0m0 2 1-1a4.2 4.2 0 0 1 6 6l-5 5a4.2 4.2 0 0 1-6 0" transform="translate(2 0)"/>', check:'<path d="m5 12 4 4L19 6"/>', clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>', trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>', spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z"/>', copy:'<rect x="8" y="8" width="12" height="13" rx="1"/><path d="M16 8V3H3v13h5"/>', book:'<path d="M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1Zm0 0v15"/>', focus:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>'
  };
  const icon = (name, size = 18) => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.arrow}</svg>`;
  const mark = '<svg class="brand-mark" viewBox="0 0 40 40" fill="currentColor" aria-hidden="true"><path d="M18 0h4v13.1l9.3-9.3 2.9 2.9-9.3 9.3H38v4H24.9l9.3 9.3-2.9 2.9-9.3-9.3V36h-4V22.9l-9.3 9.3-2.9-2.9 9.3-9.3H2v-4h13.1L5.8 6.7l2.9-2.9 9.3 9.3V0Z"/></svg>';
  const brand = () => `<a class="brand" href="/" aria-label="FOLIO home">${mark}<span data-no-i18n>${esc(state.site?.settings?.title || 'FOLIO')}</span></a>`;
  const date = (v, short = false, time = false) => v && !Number.isNaN(Date.parse(v)) ? `<time data-i18n-date="${esc(v)}" data-date-short="${short}" data-date-time="${time}">${I18n.formatDate(v,short,time)}</time>` : I18n.t('date.unpublished');
  const words = s => { const text=String(s||''); const cjk=(text.match(/[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}\p{Script=Hangul}]/gu)||[]).length; return cjk+(text.replace(/[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}\p{Script=Hangul}]/gu,' ').match(/[\p{L}\p{N}]+/gu)||[]).length; };
  const readTime = p => Math.max(1, Math.ceil(words(p.markdown || p.excerpt || '') / 210));
  const loading = () => '<div class="loading-screen"><div class="spinner"></div><span>A moment, please.</span></div>';
  const safeMedia = v => typeof v === 'string' && /^\/media\/[a-zA-Z0-9._-]+$/.test(v) ? v : '';
  let toastTimer, previousFocus;
  function toast(message, error = false) { const t = $('#toast'); t.textContent = I18n.text(message); t.className = `visible${error ? ' error' : ''}`; clearTimeout(toastTimer); toastTimer = setTimeout(() => { t.className = ''; }, error ? 6000 : 3300); }
  async function api(path, options = {}) { const res = await fetch(path, { ...options, headers: { 'Accept':'application/json', 'Accept-Language':I18n.locale, ...(options.body ? {'Content-Type':'application/json'} : {}), ...options.headers } }); let data; try { data = await res.json(); } catch { throw new Error(`The server returned an unreadable response (${res.status}).`); } if (!res.ok || data.ok === false) { const e = new Error(data.error?.message || data.message || `Request failed (${res.status})`); e.code = data.error?.code || String(res.status); e.status = res.status; throw e; } return data; }
  const op = async (name, data = {}) => { const res = await api(`/api/op/${name}`, { method:'POST', headers:{'Authorization':`Bearer ${state.token}`}, body:JSON.stringify(data) }); return res.data ?? res; };
  async function loadSite(force = false) { if (!state.site || force) { state.site = await api('/api/public/site'); state.site.posts ||= []; state.site.settings ||= {}; } return state.site; }
  function header(active = '') { return `<header class="site-header">${brand()}<nav class="header-nav" aria-label="Main navigation"><a href="/" class="${active === 'journal' ? 'active' : ''}">Journal</a><a href="/topics" class="${active === 'topics' ? 'active' : ''}">Topics</a><a href="/about" class="${active === 'about' ? 'active' : ''}">About</a></nav><div class="header-actions">${I18n.control()}<button class="icon-btn" data-action="command" aria-label="Search and commands" title="Search · Ctrl/⌘ K">${icon('search',17)}</button><a href="/studio" class="studio-link">The studio ${icon('northeast',12)}</a><button class="icon-btn mobile-menu" data-action="mobile-nav" aria-label="Toggle navigation" aria-expanded="false">${icon('menu',17)}</button></div></header><nav id="mobile-nav" class="mobile-nav hidden" aria-label="Mobile navigation"><a href="/">Journal</a><a href="/topics">Topics</a><a href="/about">About</a></nav>`; }
  function footer() { return `<footer class="site-footer"><div class="footer-left">${brand()}<span>A small corner of the internet.</span></div><div class="footer-right"><span data-no-i18n>© ${new Date().getFullYear()} ${esc(state.site?.settings?.author || 'FOLIO')}</span><a href="/feed.xml" data-native>RSS feed ↗</a><a href="/studio">Made with intention</a></div></footer>`; }
  function publicShell(content, active = 'journal') { return `<div class="shell">${header(active)}<main id="main" class="animation-in">${content}</main>${footer()}</div>`; }
  function art(post, index = 0) { const cover = safeMedia(post?.cover); const kinds = ['orange','sage','lilac','sand','blue']; const kind = kinds[index % kinds.length]; let inner = ''; if (cover) inner = `<img src="${esc(cover)}" alt="" loading="lazy">`; else if (kind === 'orange') inner = `<div class="art-grid"></div><div class="sculpture">${Array.from({length:15}, (_,i) => `<i style="--i:${i}"></i>`).join('')}</div>`; else if (kind === 'sage') inner = '<span class="giant-asterisk">✳</span>'; else if (kind === 'lilac') inner = `<div class="book-stack">${Array.from({length:5}, (_,i) => `<i style="--i:${i}">${i === 4 ? '<small>FIELD NOTES</small>Aa<small>KEEP LOOKING</small>' : ''}</i>`).join('')}</div>`; else if (kind === 'sand') inner = '<div class="sun-rays"></div>'; else inner = '<div class="windows"><i></i><i></i><i></i></div>'; return `<div class="artwork ${kind}" aria-hidden="true">${inner}${cover ? '' : `<span class="art-number">FIG. ${String(index + 1).padStart(2,'0')}</span><span class="art-sign">F / ${new Date().getFullYear()}</span>`}</div>`; }
  function postMeta(p) { return `<div class="meta"><span class="category" ${p.category||p.tags?.[0]?'data-no-i18n':''}>${esc(p.category || p.tags?.[0] || 'Journal')}</span><span>·</span><span>${readTime(p)} min read</span></div>`; }
  function postCard(p, index) { return `<article class="post-card"><a class="card-image" href="/posts/${url(p.slug)}" aria-label="Read ${esc(p.title)}">${art(p,index)}</a>${postMeta(p)}<h3 data-no-i18n><a href="/posts/${url(p.slug)}">${esc(p.title)}</a></h3><p data-no-i18n>${esc(p.excerpt || '')}</p><div class="card-bottom"><span class="meta">${date(p.published_at || p.created_at)}</span><a class="card-arrow" href="/posts/${url(p.slug)}" aria-label="Read ${esc(p.title)}">${icon('northeast',18)}</a></div></article>`; }
  function home() { const posts = state.site.posts; const feature = posts.find(p => p.featured) || posts[0]; const rest = posts.filter(p => p.id !== feature?.id); const categories = [...new Set(rest.map(p => p.category).filter(Boolean))]; return publicShell(`<section class="hero"><div><div class="eyebrow"><span class="dot"></span>An independent journal by ${esc(state.site.settings.author || 'a curious human')}</div><h1>A little curiosity.<br>A lot to <em>write about.</em></h1><div class="hero-bottom"><p ${state.site.settings.description?'data-no-i18n':''}>${esc(state.site.settings.description || 'Ideas, observations, and small discoveries. A collection of things that make me pause, think, and look a little closer.')}</p></div></div><div class="hero-art" aria-hidden="true"><span class="orbit"></span><span class="orbit"></span><span class="orbit"></span><svg class="star" viewBox="0 0 100 100" fill="currentColor"><path d="m50 0 7 33L79 10 67 41l33 9-33 9 12 31-22-23-7 33-7-33L21 90l12-31L0 50l33-9L21 10l22 23z"/></svg><span class="orbit-dot"></span><span class="tiny-cross">+</span><span class="art-caption">Always a work in progress</span></div><span class="hero-edition">NOTES FROM THE EVERYDAY / VOL. 01</span></section>${feature ? `<section aria-label="Featured story"><div class="section-top"><h2 class="section-title"><span class="dot"></span>In the spotlight</h2><span class="meta" style="font-size:12px;color:var(--muted)">One idea to spend time with</span></div><article class="featured"><a class="featured-image" href="/posts/${url(feature.slug)}" aria-label="Read ${esc(feature.title)}"><span class="feature-label">Featured essay</span>${art(feature,0)}</a><div class="featured-content"><div>${postMeta(feature)}<h2 data-no-i18n><a href="/posts/${url(feature.slug)}">${esc(feature.title)}</a></h2><p data-no-i18n>${esc(feature.excerpt)}</p></div><a class="read-story" href="/posts/${url(feature.slug)}"><span>Read the story</span><span class="arrow-circle">${icon('arrow',16)}</span></a></div></article></section>` : '<section class="empty-state"><h2>A fresh page.</h2><p>The first story is still taking shape. Come back soon.</p><a class="button" href="/studio">Open the studio</a></section>'}<section class="latest"><div class="section-top"><h2 class="section-title">The latest pages <span>(${String(rest.length).padStart(2,'0')})</span></h2><div class="filter-pills" role="group" aria-label="Filter stories"><button class="filter-pill active" data-category="">All writing</button>${categories.slice(0,3).map(c => `<button class="filter-pill" data-no-i18n data-category="${esc(c)}">${esc(c)}</button>`).join('')}</div></div><div class="post-grid" id="home-post-grid">${rest.map((p,i) => postCard(p,i+1)).join('')}</div></section><aside class="home-note"><span class="note-icon" aria-hidden="true">✳</span><div><h3>Good things take a little wandering.</h3><p>A place for unfinished thoughts, fresh perspectives, and the things in between.</p></div><a class="button secondary" href="/about">A little about me ${icon('northeast',14)}</a></aside>`); }
  function topics() { const counts = new Map(); state.site.posts.forEach(p => (p.tags || []).forEach(t => counts.set(t, (counts.get(t)||0)+1))); return publicShell(`<div class="page-heading"><div class="eyebrow"><span class="dot"></span>Follow your curiosity</div><h1>A few recurring themes.</h1><p>Different threads. One very curious mind.</p></div><div class="topic-list">${[...counts.entries()].sort((a,b) => b[1]-a[1]).map(([tag,n],i) => `<a class="topic-tile" href="/tag/${url(tag)}"><div class="topic-arrow"><span class="small-label">${String(i+1).padStart(2,'0')} / Topic</span>${icon('northeast',17)}</div><h2 data-no-i18n>${esc(tag)}</h2><p>${n} ${n === 1 ? 'story' : 'stories'} to explore</p></a>`).join('') || '<p class="muted">Topics will appear when the first stories are published.</p>'}</div>`, 'topics'); }
  function tagPage(tag) { const posts = state.site.posts.filter(p => p.tags?.includes(tag)); return publicShell(`<div class="page-heading"><a class="text-link" href="/topics">${icon('back',14)} All topics</a><h1 data-no-i18n>${esc(tag)}</h1><p>${posts.length} ${posts.length === 1 ? 'story' : 'stories'} in this collection</p></div><section class="latest all-posts"><div class="post-grid">${posts.map((p,i) => postCard(p,i+1)).join('')}</div></section>`, 'topics'); }
  function about() { const author = state.site.settings.author || 'The author'; return publicShell(`<section class="about-layout"><div><div class="eyebrow"><span class="dot"></span>The person behind the pages</div><h1>Hi, I’m ${esc(author.split(' ')[0])}.<br>Glad you found<br>your way here.</h1><p data-no-i18n>${esc(state.site.settings.description)}</p><p>This is my little corner of the internet: a place to think out loud, connect the dots, and keep a record of what catches my attention.</p><p>No grand thesis. Just a practice of paying attention, and a belief that good ideas get better when we share them.</p><a href="/" class="button secondary">Explore the journal ${icon('arrow',15)}</a></div><div class="about-graphic" aria-hidden="true"><span class="about-letter" data-no-i18n>${esc(author[0] || 'F')}.</span><span class="meta">A HUMAN BEHIND EVERY WORD<br>EST. ${new Date().getFullYear()}</span></div></section>`, 'about'); }
  async function searchPage(query) { const data = query ? await api(`/api/public/search?q=${url(query)}`) : {posts:state.site.posts}; const posts = data.posts || data.results || []; return publicShell(`<div class="page-heading"><div class="eyebrow"><span class="dot"></span>A thread worth following</div><h1>Find something good.</h1><form id="public-search" class="search-field">${icon('search',19)}<label for="search-query" class="sr-only">Search stories</label><input id="search-query" name="q" value="${esc(query)}" placeholder="Search ideas, topics, or a phrase…"><button type="submit">Search ↗</button></form></div><section class="search-results"><div class="section-top" style="padding-top:0"><h2 class="section-title">${query ? `${posts.length} ${posts.length === 1 ? 'result' : 'results'} for “${esc(query)}”` : 'All stories'}</h2></div>${posts.length ? `<div class="post-grid">${posts.map((p,i) => postCard(p,i+1)).join('')}</div>` : '<div class="empty-state"><h2>Nothing here just yet.</h2><p>Try a different word or browse the topics.</p><a href="/topics" class="button secondary">Explore topics</a></div>'}</section>`); }
  async function article(slug) { const {post:p} = await api(`/api/public/posts/${url(slug)}`); if (!p) throw new Error('This story could not be found.'); document.title = `${p.title} — ${state.site.settings.title || 'FOLIO'}`; document.documentElement.dataset.pageTitleKind='article'; const author = state.site.settings.author || 'The author'; return publicShell(`<article class="article-shell"><a class="article-back" href="/">${icon('back',14)} Back to the journal</a><header class="article-head"><div class="meta" ${p.category||p.tags?.[0]?'data-no-i18n':''}>${esc(p.category || p.tags?.[0] || 'Journal')}</div><h1 data-no-i18n>${esc(p.title)}</h1><p class="article-deck" data-no-i18n>${esc(p.excerpt)}</p><div class="article-byline"><span class="author-avatar" data-no-i18n>${esc(author[0])}</span><span><span data-no-i18n>${esc(author)}</span><br><span class="muted">${date(p.published_at)} &nbsp; · &nbsp; ${readTime(p)} min read</span></span></div></header><div class="article-cover">${art(p,Math.max(0,state.site.posts.findIndex(x=>x.id===p.id)))}</div><div class="prose">${p.html || '<p>This story is taking shape.</p>'}</div><div class="article-end"><div class="tag-links">${(p.tags || []).map(t => `<a href="/tag/${url(t)}" class="tag-link" data-no-i18n>${esc(t)}</a>`).join('')}</div><button class="text-link" data-action="share">${icon('link',14)} Copy story link</button></div></article><section class="latest"><div class="section-top"><h2 class="section-title">A little more to explore</h2><a class="text-link" href="/">All writing ${icon('arrow',14)}</a></div><div class="post-grid">${state.site.posts.filter(x=>x.id!==p.id).slice(0,3).map((p,i)=>postCard(p,i+1)).join('')}</div></section>`); }
  function studioShell(content, selected='posts', actions='') { return `<div class="studio-shell"><aside class="studio-sidebar">${brand()}<span class="small-label">Your workspace</span><nav class="studio-nav" aria-label="Studio navigation">${[['posts','posts','Writing','/studio'],['media','image','Media','/studio/media'],['settings','settings','Settings','/studio/settings'],['proposals','spark','Proposals','/studio/proposals'],['schedules','clock','Schedules','/studio/schedules'],['migration','download','Migration','/studio/migration'],['tools','terminal','Agent tools','/studio/tools']].map(([key,i,label,href])=>`<a href="${href}" class="${selected===key?'active':''}">${icon(i,17)}${label}</a>`).join('')}</nav><div class="sidebar-bottom"><button data-action="command">${icon('search',14)} Quick command <span style="margin-left:auto">⌘K</span></button><a href="/">${icon('northeast',14)} View your journal</a><button data-action="logout">${icon('logout',14)} Lock studio</button></div></aside><div class="studio-main"><header class="studio-topbar"><div class="breadcrumb">Studio <span>/</span> <strong>${selected==='posts'?'Writing':selected==='tools'?'Agent tools':selected==='media'?'Media library':selected==='proposals'?'Proposals':selected==='schedules'?'Schedules':selected==='migration'?'Migration':'Settings'}</strong></div>${I18n.control()}${actions || `<div class="studio-topbar-right"><span class="connection"><span class="dot"></span>Your space, your words</span><button class="icon-btn" data-action="command" aria-label="Quick command">${icon('search',16)}</button><a class="text-link" href="/">View journal ${icon('northeast',13)}</a><button class="icon-btn" data-action="logout" aria-label="Lock studio">${icon('logout',15)}</button></div>`}</header><main id="main" class="studio-body animation-in">${roleNotice()}${content}</main></div></div>`; }
  function login() { return `<main id="main" class="login-page"><section class="login-art">${brand()}<div><h1>A quiet space<br>for your next<br><em>good idea.</em></h1><p>Gather your thoughts. Find the right words. Share something worth reading.</p></div><div class="login-bottom">YOUR WORDS. YOUR CORNER OF THE INTERNET.</div></section><section class="login-form-wrap"><form id="login-form" class="login-form"><div class="login-locale">${I18n.control()}</div><div class="eyebrow"><span class="dot"></span>Welcome to the studio</div><h2>Let’s make something.</h2><p>Enter your access token to open your private writing workspace.</p><div class="field"><label for="access-token">Studio access token</label><input id="access-token" type="password" autocomplete="off" placeholder="Paste your access token" required autofocus></div><div id="login-error" class="inline-error" role="alert"></div><button class="button orange" type="submit">Open the studio ${icon('arrow',15)}</button><p class="login-help">Your token stays in this browser session only. Find the configured token in your server environment or setup instructions. Close this browser tab or lock the studio to clear access.</p><a class="login-back" href="/">${icon('back',14)} Back to the journal</a></form></section></main>`; }
  function statusBadge(p) { const status = p.published_revision ? (p.revision > p.published_revision ? 'changed' : 'published') : 'draft'; return `<span class="badge ${status === 'changed'?'unsaved':status}">${status === 'changed'?'Unpublished edits':status === 'published'?'Published':'Draft'}</span>`; }
  function postRows() { const filtered = state.posts.filter(p => { const status = p.published_revision ? (p.revision > p.published_revision ? 'changed':'published'):'draft'; return (state.listFilter === 'all' || state.listFilter === status) && `${p.title} ${p.slug} ${(p.tags||[]).join(' ')}`.toLowerCase().includes(state.listQuery.toLowerCase()); }); return filtered.length ? filtered.map(p => `<tr><td><a class="post-title" data-no-i18n href="/studio/posts/${url(p.id)}">${esc(p.title)}</a><span class="post-slug" data-no-i18n>/${esc(p.slug)}</span></td><td>${statusBadge(p)}</td><td class="date-column">${date(p.updated_at,true)}</td><td><a class="icon-btn" href="/studio/posts/${url(p.id)}" aria-label="Edit ${esc(p.title)}">${icon('edit',15)}</a></td></tr>`).join('') : '<tr><td colspan="4" style="padding:40px;text-align:center">No writing here yet. Start a draft or try another filter.</td></tr>'; }
  async function studioPosts() { const data = await op('posts.list'); state.posts = data.posts || []; const published = state.posts.filter(p=>p.published_revision).length; const drafts = state.posts.filter(p=>!p.published_revision).length; return studioShell(`<div class="studio-page-title"><div><h1>Your writing, in progress.</h1><p>A home for your ideas, from the first spark to the final word.</p></div>${can('posts.create')?`<a class="button orange" href="/studio/new">${icon('plus',15)} New story</a>`:''}</div><div class="studio-summary"><div class="summary-item"><span class="small-label">All stories</span><strong>${String(state.posts.length).padStart(2,'0')}</strong></div><div class="summary-item"><span class="small-label">Out in the world</span><strong>${String(published).padStart(2,'0')}</strong></div><div class="summary-item"><span class="small-label">Taking shape</span><strong>${String(drafts).padStart(2,'0')}</strong></div></div><div class="posts-toolbar"><div class="studio-tabs" role="group" aria-label="Filter writing">${[['all','All writing'],['draft','Drafts'],['published','Published'],['changed','Changed']].map(([key,label])=>`<button class="${state.listFilter===key?'active':''}" data-post-filter="${key}">${label}</button>`).join('')}</div><label class="post-search">${icon('search',14)}<input id="studio-search" placeholder="Find a story…" aria-label="Search your writing" value="${esc(state.listQuery)}"></label></div><table class="post-table"><thead><tr><th>Story</th><th>Status</th><th class="date-column">Last touched</th><th><span class="sr-only">Edit</span></th></tr></thead><tbody id="post-rows">${postRows()}</tbody></table><aside class="studio-note">${icon('spark',22)}<div><h3>Not every idea needs to be a whole story. Yet.</h3><p>Catch a thought while it’s fresh. Keep it private, then give it room to grow.</p><button class="text-link" style="margin-top:10px;color:var(--orange)" data-action="capture">Capture an idea ${icon('plus',12)}</button></div></aside>`); }
  function editorDataFromFields() { const e = state.editor; if (!e) return null; return { title:$('#post-title') ? $('#post-title').value.trim() : e.post.title, slug:$('#post-slug')?.value.trim() || '', markdown:$('#post-markdown')?.value ?? e.post.markdown, excerpt:$('#post-excerpt')?.value || '', tags:($('#post-tags')?.value || '').split(',').map(s=>s.trim()).filter(Boolean), category:$('#post-category')?.value.trim() || '', cover:$('#post-cover')?.value.trim() || '', featured:$('#post-featured')?.checked || false }; }
  function editorActions() { return `<div class="editor-top-actions"><span class="save-state" id="save-state">${state.dirty?'Unsaved changes':state.editor?.post.id?'All changes saved':'New draft'}</span><button class="button secondary small" data-action="preview">${icon('eye',13)} Preview</button>${can('posts.update')?'<button class="button secondary small" data-action="save">Save draft</button>':''}${can('schedules.create')?'<button class="button secondary small" data-action="schedule">Schedule</button>':''}${can('posts.publish')?`<button class="button orange small" data-action="publish">Publish ${icon('northeast',12)}</button>`:''}</div>`; }
  async function editor(id) { state.editor = id ? await op('posts.get',{id}) : {post:{title:'',slug:'',markdown:'',excerpt:'',tags:[],category:'',cover:'',featured:false,revision:0,published_revision:0},revisions:[],live:null}; state.dirty = false; state.viewMode='write'; return editorView(); }
  function editorView() { const {post:p,revisions=[]} = state.editor; return studioShell(`<div class="editor-layout"><section class="editor-panel"><label for="post-title" class="sr-only">Story title</label><textarea id="post-title" class="editor-title" placeholder="Give your idea a title…" rows="2">${esc(p.title)}</textarea><div class="editor-description">Your next story starts with one sentence. The rest can follow.</div><div class="editor-file-actions">${p.id&&can('proposals.create')?`<button class="text-link" data-action="submit-proposal">${icon('spark',14)} Submit as proposal</button>`:''}<label class="text-link" for="markdown-import">${icon('upload',14)} Import Markdown</label><input id="markdown-import" type="file" accept=".md,.markdown,.txt,text/markdown,text/plain" class="sr-only"><button class="text-link" data-action="export-markdown">${icon('download',14)} Export Markdown</button></div><div class="editor-mode-tabs" role="group" aria-label="Editor mode"><button class="active" data-editor-mode="write">Write</button><button data-editor-mode="preview">Preview</button><button class="text-link" data-action="focus" style="margin-left:auto" title="Toggle focus mode">${icon('focus',13)} Focus</button></div><div id="write-panel"><div class="editor-toolbar" aria-label="Markdown formatting"><button title="Bold" data-format="bold"><b>B</b></button><button title="Italic" data-format="italic"><em>I</em></button><button title="Heading" data-format="heading">H₂</button><span class="toolbar-divider"></span><button title="Link" data-format="link">${icon('link',14)}</button><button title="Quote" data-format="quote">❞</button><button title="List" data-format="list">☷</button><button title="Code" data-format="code">&lt;/&gt;</button><span class="toolbar-end">MARKDOWN</span></div><label for="post-markdown" class="sr-only">Story Markdown</label><textarea id="post-markdown" class="markdown-editor" spellcheck="true" placeholder="Start writing. There’s no rush…">${esc(p.markdown)}</textarea><div class="editor-foot"><span id="word-count">${words(p.markdown)} words · ${readTime(p)} min read</span><span>⌘ / Ctrl + S to save</span></div></div><div id="preview-panel" class="editor-preview hidden"><div class="prose" id="preview-content"></div></div></section><aside class="editor-sidebar"><div class="panel-label">Story details ${statusBadge(p)}</div><div class="field"><label for="post-slug">URL slug</label><input id="post-slug" value="${esc(p.slug)}" placeholder="a-good-place-to-start"><small>Lowercase words, separated by hyphens.</small></div><div class="field"><label for="post-excerpt">A short introduction</label><textarea id="post-excerpt" rows="3" placeholder="What’s this story about?">${esc(p.excerpt)}</textarea></div><div class="field"><label for="post-category">Category</label><input id="post-category" value="${esc(p.category)}" placeholder="e.g. Reflections"></div><div class="field"><label for="post-tags">Topics</label><input id="post-tags" value="${esc((p.tags||[]).join(', '))}" placeholder="design, everyday, ideas"><small>Separate topics with commas.</small></div><div class="field"><label for="post-cover">Cover image</label><input id="post-cover" value="${esc(p.cover)}" placeholder="/media/your-image.jpg"><small><a href="/studio/media" style="text-decoration:underline">Copy an image URL from your media library</a>, or leave blank for a FOLIO illustration.</small></div><label class="checkbox-label"><input id="post-featured" type="checkbox" ${p.featured?'checked':''}> Feature on the journal home</label><div class="editor-sidebar-section" id="revision-history" aria-label="Revision history">${revisionHistoryMarkup(p,revisions)}</div>${p.id&&can('posts.delete')?`<div class="editor-sidebar-section"><button class="text-link" data-action="delete" style="color:#ac422c">${icon('trash',13)} Move to trash</button>${p.published_revision?'<button class="text-link" data-action="unpublish" style="display:flex;margin-top:15px">Unpublish story</button>':''}</div>`:''}</aside></div>`, 'posts', editorActions()); }
  function revisionHistoryMarkup(post, revisions) {
    return `<div class="panel-label">Revision history <span id="revision-count">${revisions.length}</span></div><div class="revision-list">${revisions.length ? revisions.slice().sort((a,b)=>b.revision-a.revision).slice(0,8).map(r=>`<div class="revision-row" data-revision="${r.revision}"><div>Revision ${r.revision}${r.revision===post.published_revision?' · live':''}<small>${date(r.updated_at || r.created_at)}</small></div>${r.revision!==post.revision&&can('posts.restore')?`<button data-restore="${r.revision}">Restore</button>`:r.revision===post.revision?'<span class="muted revision-current">Current</span>':'<span class="muted">Read only</span>'}</div>`).join('') : '<p class="revision-empty">Your first save begins the story.</p>'}</div>`;
  }
  function reflectCommittedRevision(savedPost) {
    // The write response is the exact committed immutable revision. Merge it into
    // loaded history rather than refetching/replacing any editable DOM or buffer.
    const revisions = state.editor.revisions || [];
    state.editor.revisions = [...revisions.filter(r=>r.revision!==savedPost.revision), {...savedPost,tags:[...(savedPost.tags||[])]}];
    const historyRegion = $('#revision-history');
    if(historyRegion) historyRegion.innerHTML = revisionHistoryMarkup(savedPost,state.editor.revisions);
  }
  function markDirty() { state.dirty = true; const el = $('#save-state'); if(el) el.textContent='Unsaved changes'; }
  function reflectSaved() { const el=$('#save-state'); if(el) el.textContent=state.dirty?'Unsaved changes':'All changes saved'; }
  async function saveDraft(silent = false) {
    if(state.busy) return null;
    const editorSession = state.editor;
    if(!editorSession) return null;
    if(editorSession.post.id&&!state.dirty&&!editorSession.pendingWrite){
      if(!silent) toast('Your draft is already saved.');
      return editorSession.post;
    }
    const data = editorDataFromFields();
    if(!data) return null;
    // An unacknowledged write keeps its exact payload and retry key. Resolve it
    // first, even if the user has since edited: newer text remains dirty and is
    // sent by a subsequent save using the acknowledged post ID and revision.
    let pending = editorSession.pendingWrite;
    if(!pending){
      if(!data.title) throw new Error('Give your story a title before saving.');
      if(!data.slug) throw new Error('Add a URL slug using lowercase words and hyphens.');
      const post = editorSession.post;
      const key = crypto.randomUUID();
      pending = {operation:post.id?'posts.update':'posts.create',payload:{...data,...(post.id?{id:post.id,expected_revision:post.revision}:{}),idempotency_key:key},fingerprint:JSON.stringify(data),key};
      editorSession.pendingWrite = pending;
    }
    state.busy = true;
    if($('#save-state')) $('#save-state').textContent='Saving…';
    try {
      const result = await op(pending.operation,pending.payload);
      editorSession.pendingWrite = null;
      editorSession.post = result.post;
      if(state.editor!==editorSession) return result.post;
      state.dirty = pending.fingerprint!==JSON.stringify(editorDataFromFields());
      reflectSaved();
      reflectCommittedRevision(result.post);
      if(pending.operation==='posts.create') history.replaceState({},'',`/studio/posts/${url(result.post.id)}`);
      if(!silent) toast(state.dirty?'Draft saved. Your newest edits still need a save.':'Draft saved. A little further along.');
      return result.post;
    } catch(err) {
      // An explicit client error is a definite rejection. Network errors,
      // unreadable responses, and server failures retain the pending request.
      const rejected = err.status>=400&&err.status<500;
      if(rejected) editorSession.pendingWrite = null;
      const conflict = /CONFLICT|conflict|revision/i.test(err.code+err.message);
      if(state.editor===editorSession&&$('#save-state')) $('#save-state').textContent=conflict?'Conflict — your text is safe':rejected?'Save failed — text preserved':'Save unconfirmed — retry safely';
      if(conflict) err.message='A newer revision exists. Your unsaved text is still here. Copy it before reloading, then merge your changes.';
      else if(!rejected) err.message='Could not confirm whether the save completed. Retry Save to safely resolve the same request; your current text is preserved. If you edited since then, save once more after recovery to apply those edits.';
      throw err;
    } finally { state.busy=false; }
  }
  async function previewEditor() { if(state.busy)return; if(!can('posts.update')&&state.dirty)throw new Error('This token can suggest edits but cannot save or preview unsaved draft changes.'); let p=state.editor.post; if(state.dirty||!p.id) p=await saveDraft(true); if(!p)return; if(state.dirty)throw new Error('Your draft changed while saving. Save your latest edits, then preview.'); const result=await op('posts.preview',{id:p.id,revision:p.revision}); $('#preview-content').innerHTML=result.html||result.post?.html||''; $('#write-panel').classList.add('hidden'); $('#preview-panel').classList.remove('hidden'); $$('[data-editor-mode]').forEach(b=>b.classList.toggle('active',b.dataset.editorMode==='preview')); state.viewMode='preview'; }
  async function reviewPublish() { if(state.busy)return; let p=state.editor.post;if(state.dirty||!p.id)p=await saveDraft(true);if(!p)return; if(state.dirty)throw new Error('Your draft changed while saving. Save your latest edits, then publish.'); const current=await op('posts.get',{id:p.id}); if(current.post.revision!==p.revision) throw new Error('This story changed since your last save. Reload and review the latest revision.'); await op('posts.preview',{id:p.id,revision:p.revision}); const live=current.live; const changes=['title','slug','excerpt','markdown','tags','category','cover','featured'].filter(k=>JSON.stringify(p[k])!==JSON.stringify(live?.[k])); modal('One last look.',`<p>${live?'You’re about to replace the live story with this reviewed draft.':'This story will become public on your journal.'}</p><div class="publish-review"><span class="small-label">Ready to publish · Revision ${p.revision}</span><h3 data-no-i18n>${esc(p.title)}</h3><p>/${esc(p.slug)} · ${words(p.markdown)} words · ${readTime(p)} min read</p>${live?`<div class="review-versions"><div><span class="small-label">Currently live · R${live.revision}</span><strong data-no-i18n>${esc(live.title)}</strong></div><div><span class="small-label">New version · R${p.revision}</span><strong data-no-i18n>${esc(p.title)}</strong></div></div><p class="review-changes">Changed: ${changes.length?changes.map(k=>esc(k==='markdown'?'story content':k)).join(', '):'no content differences'}</p>`:'<p class="review-changes">New story · No previous public version</p>'}</div><div class="modal-actions"><button class="button secondary small" data-action="close-modal">Keep editing</button><button class="button orange small" id="confirm-publish">Publish revision ${p.revision} ${icon('northeast',12)}</button></div>`); $('#confirm-publish').onclick=async()=>{ const btn=$('#confirm-publish');btn.disabled=true;try{await op('posts.publish',{id:p.id,expected_revision:p.revision,confirm:true,idempotency_key:crypto.randomUUID()});closeModal();state.site=null;state.dirty=false;toast('Published. Your story is out in the world.');await render();}catch(err){btn.disabled=false;toast(err.message,true);}}; }
  function modal(title,body,wide=false) { closeModal(false);previousFocus=document.activeElement;const root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide-modal':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close',17)}</button></div><div class="modal-body">${body}</div></section></div>`;root.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target===e.currentTarget)closeModal();});queueMicrotask(()=>root.querySelector('input,textarea,button:not([data-action="close-modal"])')?.focus()); }
  function closeModal(restore=true) { const root=$('#modal-root');if(root)root.innerHTML='';if(restore&&previousFocus?.isConnected)previousFocus.focus();previousFocus=null; }
  async function confirmPostAction(action) { const p=state.editor.post;const labels={delete:['Move this story to trash?','The story will leave the journal. Its content remains in your backup; this is not a permanent purge.','Move to trash'],unpublish:['Take this story offline?','The public version will be removed. Your private draft and revision history stay in the studio.','Unpublish']};const [title,body,label]=labels[action];modal(title,`<p>${body}</p><p><strong data-no-i18n>${esc(p.title)}</strong></p><div class="modal-actions"><button class="button secondary small" data-action="close-modal">Cancel</button><button class="button danger small" id="confirm-action">${label}</button></div>`);$('#confirm-action').onclick=async()=>{ $('#confirm-action').disabled=true;try{await op(`posts.${action}`,{id:p.id,expected_revision:p.revision,confirm:true,idempotency_key:crypto.randomUUID()});state.dirty=false;state.site=null;closeModal();toast(action==='delete'?'Story moved to trash.':'Story is now private.');await navigate(action==='delete'?'/studio':location.pathname);}catch(err){$('#confirm-action').disabled=false;toast(err.message,true);}}; }
  function captureIdea() { modal('Catch a passing thought.',`<p>A small note now can become a good story later. This stays private.</p><form id="capture-form"><div class="field"><label for="idea-title">Give it a working title</label><input id="idea-title" placeholder="Something I’ve been thinking about…" required maxlength="200"></div><div class="field"><label for="idea-body">The idea</label><textarea id="idea-body" rows="5" placeholder="A sentence, a link, an unfinished thought…"></textarea></div><div class="modal-actions"><button type="button" class="button secondary small" data-action="close-modal">Cancel</button><button class="button orange small" type="submit">Save this idea ${icon('plus',13)}</button></div></form>`);$('#capture-form').onsubmit=async e=>{e.preventDefault();const title=$('#idea-title').value.trim();const markdown=$('#idea-body').value;const btn=$('#capture-form button[type="submit"]');btn.disabled=true;try{const result=await op('posts.create',{title,slug:slugify(title)||`idea-${Date.now()}`,markdown,tags:['idea'],category:'Notes',excerpt:'',featured:false,cover:'',idempotency_key:crypto.randomUUID()});closeModal();toast('Idea captured. You can come back to it.');navigate(`/studio/posts/${url(result.post.id)}`);}catch(err){btn.disabled=false;toast(err.message,true);}}; }
  function slugify(s){return s.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,100);}
  async function settingsPage() { const data=await op('settings.get');state.settingsRevision=data.revision;const s=data.settings;return studioShell(`<div class="studio-page-title"><div><h1>Make it your own.</h1><p>The small details that make this corner of the internet yours.</p></div></div><div class="settings-grid"><form id="settings-form" class="settings-form"><div class="form-row"><div class="field"><label for="site-title">Journal name</label><input id="site-title" name="title" value="${esc(s.title)}" required maxlength="100"></div><div class="field"><label for="site-author">Your name</label><input id="site-author" name="author" value="${esc(s.author)}" required maxlength="100"></div></div><div class="field"><label for="site-description">A short description</label><textarea id="site-description" name="description" rows="4" maxlength="500">${esc(s.description)}</textarea><small>A few words about what readers will find here. Appears on your journal and in search results.</small></div><div class="field"><label for="site-url">Public journal URL</label><input id="site-url" name="base_url" type="url" value="${esc(s.base_url)}" required><small>Used for canonical URLs and your RSS feed.</small></div><button class="button orange" type="submit">Save settings ${icon('check',15)}</button><p class="inline-error" id="settings-error" style="margin-top:15px"></p></form><aside class="settings-aside">${mark}<h3 style="margin-top:15px">A little less platform.<br>A little more you.</h3><p>Your writing is stored as portable Markdown. Your images, revisions, and settings can be exported together at any time.</p><a class="text-link" href="/studio/tools">Explore your tools ${icon('arrow',13)}</a></aside></div>`,'settings'); }
  async function mediaPage() { const data=await op('media.list');const media=data.media||[];return studioShell(`<div class="studio-page-title"><div><h1>A little visual inspiration.</h1><p>Your image library. Upload once, use wherever the story needs it.</p></div></div><label class="upload-zone" for="media-upload">${icon('upload',24)}<strong>Choose an image to add to your library</strong><p>PNG, JPG, GIF, or WebP · Up to 5 MB · No SVG</p><input id="media-upload" type="file" accept="image/png,image/jpeg,image/gif,image/webp" class="sr-only"></label><div class="media-grid">${media.map(m=>`<article class="media-card"><div class="media-thumb">${safeMedia(m.url)?`<img data-no-i18n src="${esc(m.url)}" alt="${esc(m.name)}" loading="lazy">`:icon('image',30)}</div><div class="media-info"><strong data-no-i18n title="${esc(m.name)}">${esc(m.name)}</strong><small>${(m.size/1024).toFixed(0)} KB · ${date(m.created_at,true)}</small><button data-copy="${esc(m.url)}">${icon('copy',12)} Copy image URL</button></div></article>`).join('')}</div>${!media.length?'<div class="empty-state"><h2>A blank canvas, for now.</h2><p>Add an image above. You can use its URL in a story’s cover or Markdown.</p></div>':''}`,'media'); }
  async function toolsPage(){const [info,cap]=await Promise.all([op('system.info'),op('system.capabilities')]);state.capabilities=cap;const operations=cap.operations||[];return studioShell(`<div class="studio-page-title"><div><h1>Built to work your way.</h1><p>The same publishing tools, whether you write, script, or work with an agent.</p></div><span class="badge published">v${esc(info.version||cap.version||'0.1.0')}</span></div><div class="tools-grid"><section class="tool-card">${icon('terminal',25)}<h2>Your agent’s workbench.</h2><p>Configure FOLIO_URL and FOLIO_TOKEN in your MCP client’s environment. Discover operations, draft a story, preview the exact revision, then publish with your approval.</p><div class="code-sample">FOLIO_URL=http://127.0.0.1:8080 folio mcp</div><button class="text-link" data-action="capabilities">Browse ${operations.length} available operations ${icon('arrow',14)}</button></section><section class="tool-card">${icon('book',25)}<h2>A scriptable writing practice.</h2><p>Every Studio action has a matching CLI operation. Revision checks protect your work, and draft changes leave the live story untouched.</p><div class="code-sample">folio capabilities<br>folio call posts.list --json '{}'</div><button class="text-link" data-copy="folio capabilities">${icon('copy',13)} Copy discovery command</button></section><section class="tool-card">${icon('download',25)}<h2>Your work goes with you.</h2><p>Download a complete JSON backup with stories, revision history, settings, and media. Keep a copy somewhere safe.</p><button class="button secondary small" data-action="export">Export full backup ${icon('download',13)}</button></section><section class="tool-card">${icon('upload',25)}<h2>A new home, same words.</h2><p>Restore a checksum-verified FOLIO backup into an empty instance. Existing content is never silently overwritten.</p><label class="button secondary small" for="restore-backup">Choose backup ${icon('upload',13)}</label><input id="restore-backup" type="file" accept="application/json,.json" class="sr-only"></section></div><div class="studio-note">${icon('spark',22)}<div><h3>Your creative tools, with clear boundaries.</h3><p>FOLIO exposes real publishing operations through HTTP, CLI, and MCP. It doesn’t pretend to generate text or images. Connect the creative tools you trust; review the result before it goes live.</p></div></div><details class="tools-details"><summary>Available operations &amp; exact input schemas</summary><div class="capability-list">${operations.map(o=>`<details class="capability-item"><summary><span data-no-i18n>${esc(o.name)}</span><span class="badge ${o.read_only?'published':'draft'}" data-no-i18n>${esc(o.scope||'operation')}</span></summary><p>${esc(o.description)}</p><pre class="tools-output">${esc(JSON.stringify(o.input_schema,null,2))}</pre></details>`).join('')}</div></details><details class="tools-details" id="audit-details"><summary>Recent activity &amp; audit trail</summary><div id="audit-content" class="audit-list"><button class="button secondary small" data-action="audit" style="margin-top:15px">Load activity</button></div></details><details class="tools-details"><summary>Instance information</summary><pre class="tools-output">${esc(JSON.stringify(info,null,2))}</pre></details>`,'tools');}
  const can = name => !Array.isArray(state.info?.permissions)||state.info.permissions.includes(name);
  const workflowBadge = status => `<span class="badge ${status==='approved'||status==='published'?'published':status==='pending'?'draft':'unsaved'}">${esc(({pending:'Pending review',approved:'Approved',rejected:'Rejected',cancelled:'Cancelled',published:'Published',blocked:'Blocked'})[status]||status)}</span>`;
  const roleNotice = () => !state.info?.actor||state.info.actor==='admin'?'':`<aside class="role-notice" role="note">${icon('eye',17)}<span>${state.info.actor==='proposal'?'Proposal access: suggest changes; direct writing, approval, publishing, and scheduling are unavailable.':state.info.actor==='draft'?'Draft access: edit private drafts and submit proposals. The owner approves and publishes.':'Read-only access: you can inspect content, but cannot make changes.'}</span></aside>`;
  function blockedWorkspace(selected) { return studioShell(`<div class="empty-state"><h1>Owner access is required.</h1><p>This token does not permit this workflow. Lock the studio and sign in with an appropriately scoped token.</p><button class="button secondary" data-action="logout">Lock studio</button></div>`,selected); }
  function fieldLabel(field){return ({title:'Title',slug:'URL slug',excerpt:'A short introduction',markdown:'Story content',tags:'Topics',category:'Category',cover:'Cover image',featured:'Featured'})[field]||field;}
  function plainValue(value){return Array.isArray(value)?value.join(', '):typeof value==='boolean'?String(value):String(value??'');}
  function proposalReviewHTML(proposal,review){const changes=review?.changed_fields||[];return `<section class="workflow-section"><h2>Field changes</h2><p>Read-only comparison against the exact base revision. Candidate text is never executed.</p>${changes.filter(c=>c.field!=='markdown').map(c=>`<article class="field-diff"><h3>${esc(fieldLabel(c.field))}</h3><div class="diff-columns"><div><span class="small-label">Before</span><pre data-no-i18n>${esc(plainValue(c.before))}</pre></div><div><span class="small-label">Proposed</span><pre data-no-i18n>${esc(plainValue(c.after))}</pre></div></div></article>`).join('')||'<p class="muted">No metadata changes.</p>'}</section><section class="workflow-section"><h2>Markdown changes</h2><p>The comparison preserves the original text and shows one changed range.</p><div class="markdown-diff">${(review?.markdown_diff||[]).map(chunk=>`<div class="diff-chunk diff-${['equal','add','remove'].includes(chunk.kind)?chunk.kind:'equal'}"><span class="small-label">${chunk.kind==='add'?'Added':chunk.kind==='remove'?'Removed':'Unchanged'}</span><pre data-no-i18n>${esc(chunk.text)}</pre></div>`).join('')||'<p class="muted">No Markdown changes.</p>'}</div><details class="workflow-details"><summary>Full proposed Markdown</summary><pre class="review-markdown" data-no-i18n>${esc(proposal.candidate.markdown)}</pre></details></section>`;}
  async function proposalsPage(id){if(!can('proposals.list'))return blockedWorkspace('proposals');if(id){const data=await op('proposals.get',{id});const p=data.proposal;let current=null,baseUnavailable=false;if(p.post_id){try{current=(await op('posts.get',{id:p.post_id})).post;}catch(err){if(err.status===404)baseUnavailable=true;else throw err;}}const stale=!!p.post_id&&(baseUnavailable||current?.revision!==p.base_revision);state.proposalDetail={...data,stale};return studioShell(`<a class="text-link" href="/studio/proposals">${icon('back',14)} All proposals</a><div class="studio-page-title workflow-heading"><div><div class="eyebrow">A suggestion, ready for review</div><h1 data-no-i18n>${esc(p.candidate.title)}</h1><p><span>Base revision ${p.base_revision}</span> · <span>Proposal revision ${p.revision}</span></p></div>${workflowBadge(p.status)}</div>${p.status==='pending'&&stale?'<div class="error-notice">The base draft has changed or is unavailable. Approval is blocked; nothing will be overwritten. Ask for a new proposal against the latest draft.</div>':''}<div class="workflow-meta"><span>Submitted by <span data-no-i18n>${esc(p.created_by)}</span></span><span>${date(p.created_at,false,true)}</span>${p.post_id?`<a class="text-link" href="/studio/posts/${url(p.post_id)}">Open current draft ${icon('northeast',13)}</a>`:'<span>Proposal for a new private draft</span>'}</div>${proposalReviewHTML(p,data.review)}<div class="workflow-actions">${p.status==='pending'?`${can('proposals.approve')?`<button class="button orange" data-proposal-decision="approve" ${stale?'disabled':''}>Approve to private draft</button><button class="button secondary" data-proposal-decision="reject">Reject proposal</button>`:''}${can('proposals.cancel')?'<button class="button secondary" data-proposal-decision="cancel">Withdraw proposal</button>':''}`:p.applied_post_id?`<a class="button secondary" href="/studio/posts/${url(p.applied_post_id)}">Open approved draft ${icon('northeast',14)}</a>`:'<p class="muted">This review is closed. Its record remains available.</p>'}</div><aside class="studio-note">${icon('eye',20)}<div><h3>Approval creates a private draft, never a publication.</h3><p>The live story stays unchanged. Publishing or scheduling requires a separate, explicit review.</p></div></aside>`,'proposals');}
    const status=new URLSearchParams(location.search).get('status')||'';const data=await op('proposals.list',status?{status}:{});const proposals=data.proposals||[];state.proposals=proposals;const example=`folio call proposals.create --json '${JSON.stringify({base_revision:0,candidate:{title:'A considered idea',slug:'considered-idea',markdown:'A private suggestion for the owner to review.'},idempotency_key:'proposal-example-001'})}'`;return studioShell(`<div class="studio-page-title"><div><h1>Good ideas deserve a second look.</h1><p>Review agent suggestions before they become private drafts. You decide what moves forward.</p></div></div><nav class="workflow-filters" aria-label="Filter proposals">${[['','All proposals'],['pending','Pending review'],['approved','Approved'],['rejected','Rejected'],['cancelled','Cancelled']].map(([value,label])=>`<a class="filter-pill ${status===value?'active':''}" href="/studio/proposals${value?'?status='+value:''}">${label}</a>`).join('')}</nav><div class="workflow-list">${proposals.map(p=>`<a class="workflow-card" href="/studio/proposals/${url(p.id)}"><div><h2 data-no-i18n>${esc(p.candidate.title)}</h2><p><span>Base revision ${p.base_revision}</span> · ${date(p.created_at,true)}</p></div><div>${workflowBadge(p.status)}${icon('arrow',17)}</div></a>`).join('')||'<div class="empty-state"><h2>No proposals here yet.</h2><p>An agent can submit a complete suggestion through CLI or MCP. Nothing changes until the owner approves it.</p></div>'}</div><details class="workflow-details"><summary>Submit a real proposal through CLI or MCP</summary><p>Use a proposal-scoped token. For an existing story, read its current revision and provide post_id and base_revision. The candidate replaces all author-controlled fields.</p><pre class="code-sample" data-no-i18n>${esc(example)}</pre><button class="text-link" data-copy="${esc(example)}">${icon('copy',13)} Copy example command</button></details>`,'proposals');}
  function reviewProposalDecision(action){const {proposal:p}=state.proposalDetail||{};if(!p)return;const copy={approve:['Approve this proposal?','Apply the exact candidate to a private draft only. The current base revision must still match. This does not publish the story.','Approve to private draft'],reject:['Reject this proposal?','Close this suggestion without changing the draft or the live story.','Reject proposal'],cancel:['Withdraw this proposal?','Cancel this pending suggestion. No draft or live content will change.','Withdraw proposal']}[action];if(!copy)return;const payload={id:p.id,expected_revision:p.revision,confirm:true,idempotency_key:crypto.randomUUID()};modal(copy[0],`<p>${copy[1]}</p><h3 class="review-title" data-no-i18n>${esc(p.candidate.title)}</h3><p>Proposal revision ${p.revision}</p><div class="inline-error" id="workflow-error" role="alert"></div><div class="modal-actions"><button class="button secondary small" data-action="close-modal">Cancel</button><button class="button orange small" id="workflow-confirm">${copy[2]}</button></div>`);$('#workflow-confirm').onclick=async()=>{const button=$('#workflow-confirm');button.disabled=true;try{await op(`proposals.${action}`,payload);closeModal();toast(action==='approve'?'Proposal approved into a private draft. Nothing was published.':action==='reject'?'Proposal rejected. Existing content is unchanged.':'Proposal withdrawn. Existing content is unchanged.');await render();}catch(err){button.disabled=false;$('#workflow-error').textContent=err.code==='conflict'?'The proposal or base draft changed. Nothing was overwritten. Close this dialog and reload the review.':err.message;I18n.apply($('#modal-root'));}};}
  function submitEditorProposal(){const p=state.editor?.post;if(!p?.id)throw new Error('Save a base draft before submitting a proposal.');if(state.editor.pendingWrite)throw new Error('Resolve the pending save before submitting a proposal.');const candidate=editorDataFromFields();if(!candidate.title||!candidate.slug)throw new Error('A proposal needs a title and a valid URL slug.');const payload={post_id:p.id,base_revision:p.revision,candidate,idempotency_key:crypto.randomUUID()};modal('Submit these edits for review?',`<p>The current editor text becomes an immutable proposal. Your saved draft and live story stay unchanged.</p><h3 class="review-title" data-no-i18n>${esc(candidate.title)}</h3><p>Base revision ${p.revision}</p><div id="workflow-error" class="inline-error" role="alert"></div><div class="modal-actions"><button class="button secondary small" data-action="close-modal">Keep editing</button><button class="button orange small" id="workflow-confirm">Submit proposal</button></div>`);$('#workflow-confirm').onclick=async()=>{const b=$('#workflow-confirm');b.disabled=true;try{await op('proposals.create',payload);closeModal();toast('Proposal submitted. Your editor text is unchanged; unsaved edits remain private.');}catch(err){b.disabled=false;$('#workflow-error').textContent=err.message;I18n.apply($('#modal-root'));}};}
  const localZone=()=>Intl.DateTimeFormat().resolvedOptions().timeZone||'Local time';
  const localDateInput=value=>{const d=new Date(value);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
  function futureUTC(value){const d=new Date(value);if(!value||Number.isNaN(d.getTime())||d.getTime()<=Date.now())throw new Error('Choose a future date and time.');if(localDateInput(d)!==value)throw new Error('This local time does not exist in your timezone. Choose another time.');return d.toISOString();}
  function scheduleReason(reason){return ({slug_conflict:'The pinned URL slug is now used by another story.',post_unavailable:'The scheduled story is unavailable.',invalid_snapshot:'The pinned snapshot could not be validated.',empty_snapshot:'The pinned snapshot has no content.',invalid_publish_at:'The saved publication time is invalid.',cancelled_by_publisher:'Cancelled by the publisher.','posts.publish':'Cancelled by a later manual publication.','posts.unpublish':'Cancelled by a later unpublish action.','posts.delete':'Cancelled when the story moved to trash.'})[reason]||reason;}
  async function schedulesPage(){if(!can('schedules.list'))return blockedWorkspace('schedules');const status=new URLSearchParams(location.search).get('status')||'';const data=await op('schedules.list',status?{status}:{});const schedules=data.schedules||[];state.schedules=schedules;return studioShell(`<div class="studio-page-title"><div><h1>A good moment, chosen in advance.</h1><p>Each schedule publishes one reviewed snapshot. Later draft edits stay private.</p></div><a class="button secondary" href="/studio">Choose a story ${icon('arrow',14)}</a></div>${state.info?.scheduler?.paused?'<div class="error-notice">Automatic publication is paused. Restart the server without --pause-schedules when you are ready to resume.</div>':''}<div class="workflow-zone"><span>Times shown in</span> <code data-no-i18n>${esc(localZone())}</code><span>with UTC for verification.</span></div><nav class="workflow-filters" aria-label="Filter schedules">${[['','All schedules'],['pending','Scheduled'],['published','Published'],['blocked','Blocked'],['cancelled','Cancelled']].map(([value,label])=>`<a class="filter-pill ${status===value?'active':''}" href="/studio/schedules${value?'?status='+value:''}">${label}</a>`).join('')}</nav><div class="schedule-list">${schedules.map(s=>`<article class="schedule-card"><div class="schedule-card-heading"><div><h2 data-no-i18n>${esc(s.snapshot.title)}</h2><p>Pinned revision ${s.post_revision}</p></div>${s.status==='pending'?'<span class="badge draft">Scheduled</span>':workflowBadge(s.status)}</div><div class="schedule-time"><strong>${date(s.publish_at,false,true)}</strong><code data-no-i18n>${esc(s.publish_at)} UTC</code></div>${s.reason?`<p class="schedule-reason">${esc(scheduleReason(s.reason))}</p>`:''}${s.executed_at?`<p><span>Actually published</span> ${date(s.executed_at,false,true)}</p>`:''}<details class="workflow-details"><summary>Inspect the pinned snapshot</summary><div class="snapshot-metadata"><span>URL slug</span><code data-no-i18n>${esc(s.snapshot.slug)}</code><span>Topics</span><span data-no-i18n>${esc((s.snapshot.tags||[]).join(', '))}</span></div><pre class="review-markdown" data-no-i18n>${esc(s.snapshot.markdown)}</pre></details><div class="workflow-actions"><a class="text-link" href="/studio/posts/${url(s.post_id)}">Open current draft ${icon('northeast',13)}</a>${['pending','blocked'].includes(s.status)?`<button class="button secondary small" data-schedule-reschedule="${esc(s.id)}">Reschedule & review current draft</button><button class="text-link" data-schedule-cancel="${esc(s.id)}">Cancel schedule</button>`:''}</div></article>`).join('')||'<div class="empty-state"><h2>Nothing on the calendar yet.</h2><p>Open a story in the editor and choose Schedule to review a revision and its publication time.</p></div>'}</div><aside class="studio-note">${icon('clock',21)}<div><h3>The server needs to be running.</h3><p>If it is offline at the chosen time, the saved snapshot publishes when the server restarts. Blocked schedules need your review and do not retry automatically.</p></div></aside>`,'schedules');}
  async function reviewSchedule(scheduleId=null){if(!can(scheduleId?'schedules.reschedule':'schedules.create'))throw new Error('Owner access is required.');let schedule=null,p;if(scheduleId){schedule=(await op('schedules.get',{id:scheduleId})).schedule;p=(await op('posts.get',{id:schedule.post_id})).post;}else{if(state.busy)return;p=state.editor?.post;if(!p)return;if(state.dirty||!p.id||state.editor.pendingWrite)p=await saveDraft(true);if(!p)return;if(state.dirty)throw new Error('Save the latest editor changes before scheduling.');const current=(await op('posts.get',{id:p.id})).post;if(current.revision!==p.revision)throw new Error('The draft changed. Reload and review its latest revision before scheduling.');p=current;}const preview=await op('posts.preview',{id:p.id,revision:p.revision});if(!p.markdown.trim())throw new Error('Cannot publish an empty post');const defaultAt=localDateInput(Date.now()+60*60*1000);modal(schedule?'Review a new time and revision.':'Choose when this story goes live.',`<div class="publish-review"><span class="small-label">Pinned revision ${p.revision}</span><h3 data-no-i18n>${esc(p.title)}</h3><p>${schedule?`This replaces pinned revision ${schedule.post_revision} with the current draft revision ${p.revision}.`:'Only this exact snapshot will publish. Later edits remain private.'}</p></div><details class="workflow-details"><summary>Review the exact snapshot</summary><div class="prose snapshot-preview">${preview.html||preview.post?.html||''}</div></details><form id="schedule-form"><div class="field"><label for="schedule-at">Publication date and time</label><input id="schedule-at" type="datetime-local" required value="${defaultAt}" min="${localDateInput(Date.now()+60000)}"><small><span>Browser timezone</span>: <span data-no-i18n>${esc(localZone())}</span></small></div><div class="schedule-utc"><span>UTC confirmation</span><output id="schedule-utc" data-no-i18n></output></div><label class="checkbox-label"><input id="schedule-approved" type="checkbox" required><span>I approve publication of this exact revision at the time shown.</span></label><p class="inline-error" id="workflow-error" role="alert"></p><div class="modal-actions"><button type="button" class="button secondary small" data-action="close-modal">Cancel</button><button type="submit" class="button orange small">${schedule?'Confirm new time & revision':'Confirm scheduled publication'}</button></div></form>`,true);const input=$('#schedule-at');const showUTC=()=>{try{$('#schedule-utc').textContent=futureUTC(input.value);}catch{$('#schedule-utc').textContent='—';}};input.addEventListener('input',showUTC);showUTC();let pending=null;$('#schedule-form').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button[type="submit"]');try{if(!$('#schedule-approved').checked)throw new Error('Confirm the pinned revision and publication time.');const publishAt=futureUTC(input.value);const payload=schedule?{id:schedule.id,expected_revision:schedule.revision,expected_post_revision:p.revision,publish_at:publishAt,confirm:true}:{post_id:p.id,expected_revision:p.revision,publish_at:publishAt,confirm:true};const fingerprint=JSON.stringify(payload);if(pending&&pending.fingerprint!==fingerprint)throw new Error('A previous schedule request is unconfirmed. Restore its displayed time and retry before changing it.');if(!pending)pending={fingerprint,payload:{...payload,idempotency_key:crypto.randomUUID()}};button.disabled=true;await op(schedule?'schedules.reschedule':'schedules.create',pending.payload);closeModal();toast(schedule?'Schedule updated with the reviewed current draft.':'Scheduled. The reviewed snapshot is pinned; later edits remain private.');await navigate('/studio/schedules');}catch(err){if(err.status>=400&&err.status<500)pending=null;button.disabled=false;$('#workflow-error').textContent=err.message;I18n.apply($('#modal-root'));}};}
  async function cancelSchedule(id){const s=(await op('schedules.get',{id})).schedule;const payload={id:s.id,expected_revision:s.revision,confirm:true,idempotency_key:crypto.randomUUID()};modal('Cancel this scheduled publication?',`<p>This cancels future publication. It does not take an already published story offline.</p><h3 class="review-title" data-no-i18n>${esc(s.snapshot.title)}</h3><p>Pinned revision ${s.post_revision}</p><p>${date(s.publish_at,false,true)}</p><div class="inline-error" id="workflow-error" role="alert"></div><div class="modal-actions"><button class="button secondary small" data-action="close-modal">Keep schedule</button><button class="button danger small" id="workflow-confirm">Cancel schedule</button></div>`);$('#workflow-confirm').onclick=async()=>{const b=$('#workflow-confirm');b.disabled=true;try{await op('schedules.cancel',payload);closeModal();toast('Schedule cancelled. Existing published content is unchanged.');await render();}catch(err){b.disabled=false;$('#workflow-error').textContent=err.message;I18n.apply($('#modal-root'));}};}

  function migrationState(){return state.migration||(state.migration={files:[],conflict:'error',review:null,frozenPlanJSON:null,report:null,locked:false,error:''});}
  function downloadObject(value,name){const address=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=address;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(address),1000);}
  function migrationActionLabel(action){return ({create:'Create private draft',update:'Replace existing draft',skip:'Skip',blocked:'Blocked',applied:'Applied',skipped:'Skipped',failed:'Failed',pending:'Pending'})[action]||action;}
  function migrationDiagnostics(data){const all=[...(data.plan?.diagnostics||[]),...(data.validation_issues||[])];const seen=new Set();return all.filter(item=>{const key=JSON.stringify(item);if(seen.has(key))return false;seen.add(key);return true;});}
  function migrationPlanView(data){const plan=data.plan,summary=data.summary||{};const diagnostics=migrationDiagnostics(data);return `<section class="migration-review"><div class="section-top"><h2 class="section-title">Review the import plan</h2><button class="text-link" data-action="migration-download-plan">${icon('download',14)} Download frozen plan</button></div><div class="migration-summary">${[['create','Create'],['update','Replace drafts'],['skip','Skip'],['blocked','Blocked']].map(([key,label])=>`<div><span>${label}</span><strong>${Number(summary[key]??plan.entries.filter(e=>e.action===key).length)}</strong></div>`).join('')}</div><div class="migration-target"><span>Target instance</span><code data-no-i18n>${esc(data.target_instance_id)}</code></div>${diagnostics.length?`<div class="error-notice"><h3>Plan diagnostics</h3><ul>${diagnostics.map(d=>`<li><strong data-no-i18n>${esc(d.source_path)}</strong><span>${esc(d.message)}</span><code data-no-i18n>${esc(d.code)}</code></li>`).join('')}</ul></div>`:''}<div class="migration-entries">${plan.entries.map(entry=>{const doc=entry.document;return `<article class="migration-entry"><div class="schedule-card-heading"><div><h3 data-no-i18n>${esc(doc.title)}</h3><p data-no-i18n>${esc(doc.source_path)}</p></div><span class="badge ${entry.action==='blocked'?'unsaved':entry.action==='skip'?'':'draft'}">${migrationActionLabel(entry.action)}</span></div><div class="snapshot-metadata"><span>URL slug</span><code data-no-i18n>${esc(doc.slug)}</code>${entry.action==='update'?`<span>Expected revision</span><code data-no-i18n>${entry.expected_revision}</code>`:''}</div>${entry.action==='update'?'<p class="migration-replace-warning">This replaces every editable draft field. Missing source fields become empty or default. The live version stays unchanged.</p>':''}${(doc.warnings||[]).length?`<ul class="migration-warnings">${doc.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`:''}<details class="workflow-details"><summary>Inspect source and retained metadata</summary><div class="snapshot-metadata"><span>Source date</span><span data-no-i18n>${esc(doc.date||'—')}</span><span>Source publication date</span><span data-no-i18n>${esc(doc.publish_date||'—')}</span></div>${doc.extra&&Object.keys(doc.extra).length?`<h4>Unsupported source metadata</h4><pre class="review-markdown" data-no-i18n>${esc(JSON.stringify(doc.extra,null,2))}</pre>`:''}<pre class="review-markdown" data-no-i18n>${esc(doc.markdown)}</pre></details></article>`;}).join('')}</div>${!data.can_apply?'<div class="error-notice">This plan cannot be applied. Resolve its diagnostics and prepare a new plan.</div>':''}<div class="workflow-actions"><button class="button orange" data-action="migration-apply" ${!data.can_apply?'disabled':''}>${migrationState().locked?'Retry the same frozen plan':'Apply as private drafts'}</button><button class="button secondary" data-action="migration-reset">Discard review and choose files</button></div></section>`;}
  function migrationReportView(report){const complete=report.complete===true;return `<section class="migration-report"><div class="section-top"><h2 class="section-title">Import results</h2><button class="text-link" data-action="migration-download-report">${icon('download',14)} Download item report</button></div><div class="${complete?'success-notice':'error-notice'}">${complete?'Import complete. Every applied item is a private draft; nothing was published.':'Import is incomplete. Successfully applied drafts are retained. Retry the exact frozen plan; do not re-plan this batch.'}</div><div class="migration-outcomes">${(report.outcomes||[]).map(o=>`<article><div><strong data-no-i18n>${esc(o.source_path)}</strong><span class="badge ${o.status==='applied'?'published':o.status==='failed'?'unsaved':''}">${migrationActionLabel(o.status)}</span></div>${o.error?`<p class="inline-error">${esc(o.error)}</p>`:''}${o.post_id?`<a class="text-link" href="/studio/posts/${url(o.post_id)}">Open imported draft ${icon('northeast',13)}</a>`:''}</article>`).join('')}</div></section>`;}
  async function migrationPage(){if(!can('migration.plan')&&!can('migration.export'))return blockedWorkspace('migration');const m=migrationState();return studioShell(`<div class="studio-page-title"><div><h1>Bring your words with you.</h1><p>Review a file-by-file plan, then import only private drafts. Keep your original files and provenance.</p></div></div><aside class="studio-note migration-intro">${icon('book',22)}<div><h3>A careful move, with honest limits.</h3><p>Source dates and unsupported frontmatter are retained in the plan and manifest, not applied as publishing timestamps or schedules. Attachment links stay unchanged; images are not copied or fetched.</p></div></aside>${can('migration.plan')?`<section class="migration-input"><h2>Import Markdown files</h2><label class="upload-zone ${m.locked?'upload-locked':''}" for="migration-files">${icon('upload',24)}<strong>Choose Markdown files</strong><p>Up to 200 files and 8 MiB of source text. File contents are uploaded; the server never reads paths on your computer.</p><input id="migration-files" type="file" accept=".md,.markdown,text/markdown,text/plain" multiple class="sr-only" ${m.locked?'disabled':''}></label><div id="migration-selection" class="migration-selection">${m.files.length?`<p>Selected files: ${m.files.length}</p><ul>${m.files.map(f=>`<li data-no-i18n>${esc(f.path)}</li>`).join('')}</ul>`:'<p>No files selected.</p>'}</div><div class="field"><label for="migration-conflict">When a URL slug already exists</label><select id="migration-conflict" ${m.locked?'disabled':''}><option value="error" ${m.conflict==='error'?'selected':''}>Block and review (recommended)</option><option value="skip" ${m.conflict==='skip'?'selected':''}>Skip matching files</option><option value="update" ${m.conflict==='update'?'selected':''}>Replace matching private drafts</option></select><small>Replacement overwrites all editable fields in the matched draft, including empty source values. It never publishes.</small></div><button class="button secondary" data-action="migration-plan" ${!m.files.length||m.locked?'disabled':''}>Prepare import plan</button></section>`:''}${m.error?`<div class="error-notice" role="alert">${esc(m.error)}</div>`:''}${m.report?migrationReportView(m.report):''}${m.review?migrationPlanView(m.review):''}<section class="migration-export"><div><h2>Take your Markdown elsewhere.</h2><p>Download a portable JSON bundle containing Markdown files and their provenance manifest. Every exported file is marked draft:true. Media files are not included; use a full backup for everything.</p></div><div class="field"><label for="migration-export-status">Export selection</label><select id="migration-export-status"><option value="all">All writing</option><option value="draft">Drafts</option><option value="published">Published</option></select></div><button class="button secondary" data-action="migration-export" ${!can('migration.export')?'disabled':''}>Download Markdown bundle (.json) ${icon('download',14)}</button><a class="text-link" href="/studio/tools">Open full backup tools ${icon('arrow',13)}</a></section>`,'migration');}
  async function selectMigrationFiles(input){const m=migrationState();if(m.locked)return;const chosen=[...(input.files||[])];if(!chosen.length)return;if(chosen.length>200)throw new Error('Choose no more than 200 Markdown files.');if(chosen.reduce((sum,file)=>sum+file.size,0)>8*1024*1024)throw new Error('The selected source files exceed the 8 MiB import limit.');if(chosen.some(file=>!(/\.(md|markdown)$/i.test(file.name))))throw new Error('Choose Markdown files ending in .md or .markdown.');const files=[];for(const file of chosen){let content;try{content=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());}catch{throw new Error('A selected file is not valid UTF-8 text. Save it as UTF-8 and try again.');}files.push({path:file.name,content});}m.files=files;m.review=null;m.frozenPlanJSON=null;m.report=null;m.error='';await render();}
  async function prepareMigration(){const m=migrationState();if(!m.files.length||m.locked)return;const button=$('[data-action="migration-plan"]');if(button)button.disabled=true;m.error='';try{const data=await op('migration.plan',{files:m.files,conflict:m.conflict});if(!data.plan||!Array.isArray(data.plan.entries)||!data.target_instance_id)throw new Error('The server returned an incomplete import plan. No changes were applied.');m.review=data;m.frozenPlanJSON=JSON.stringify(data.plan);m.report=null;await render();}catch(err){m.error=err.message;await render();}}
  function confirmMigration(){const m=migrationState();if(!m.review?.can_apply||!m.frozenPlanJSON)return;const plan=JSON.parse(m.frozenPlanJSON);const creates=plan.entries.filter(e=>e.action==='create').length,updates=plan.entries.filter(e=>e.action==='update').length;modal('Apply this reviewed import plan?',`<p>Create ${creates} private drafts and replace ${updates} existing drafts.</p><p>Successful items are retained if a later item fails. Nothing is published. Retry this same frozen plan after any partial or unconfirmed result.</p><div class="migration-target"><span>Target instance</span><code data-no-i18n>${esc(m.review.target_instance_id)}</code></div><div class="inline-error" id="workflow-error" role="alert"></div><div class="modal-actions"><button class="button secondary small" data-action="close-modal">Keep reviewing</button><button class="button orange small" id="workflow-confirm">Apply as private drafts</button></div>`);const payload={plan,target_instance_id:m.review.target_instance_id,confirm:true,continue_on_error:false};$('#workflow-confirm').onclick=async()=>{const button=$('#workflow-confirm');button.disabled=true;m.locked=true;m.error='';try{const data=await op('migration.apply',payload);if(!data.report||!Array.isArray(data.report.outcomes))throw new Error('The import result could not be confirmed. Preserve this frozen plan and retry it.');m.report=data.report;m.locked=!data.report.complete;closeModal();toast(data.report.complete?'Import complete. All imported items are private drafts.':'Import partially completed. Review every item and retry the same plan.');await render();}catch(err){m.error=err.message;button.disabled=false;$('#workflow-error').textContent=err.message;I18n.apply($('#modal-root'));}};}
  async function exportMigration(){const status=$('#migration-export-status')?.value||'all';const button=$('[data-action="migration-export"]');if(button)button.disabled=true;try{const bundle=await op('migration.export',{status});if(!Array.isArray(bundle.files)||!bundle.manifest)throw new Error('The server returned an incomplete Markdown bundle.');downloadObject(bundle,`folio-markdown-${new Date().toISOString().slice(0,10)}.json`);toast('Portable Markdown bundle exported with its provenance manifest.');}finally{if(button)button.disabled=false;}}
  async function resetMigration(){const m=migrationState();if(m.locked&&!confirm(I18n.text('This import may have partial or unconfirmed results. Download the frozen plan before discarding it. Start a new review anyway?')))return;state.migration={files:[],conflict:'error',review:null,frozenPlanJSON:null,report:null,locked:false,error:''};await render();}

  let paletteItems=[], paletteSelection=0;
  function commandPalette() {
    const inStudio=location.pathname.startsWith('/studio')&&state.token;
    const navs=[{title:'Explore the journal',detail:'All published stories',icon:'book',href:'/'},{title:'Browse topics',detail:'Follow a thread of curiosity',icon:'spark',href:'/topics'},{title:'About the author',detail:'The person behind the pages',icon:'posts',href:'/about'},{title:'Open the studio',detail:'Your private writing workspace',icon:'edit',href:'/studio'}];
    if(inStudio)navs.unshift({title:'Write a new story',detail:'Begin with a blank page',icon:'plus',href:'/studio/new'},{title:'Capture an idea',detail:'A thought to come back to',icon:'spark',action:'capture'},{title:'Media library',detail:'Your images and illustrations',icon:'image',href:'/studio/media'},{title:'Agent tools',detail:'CLI, MCP, backups, and capabilities',icon:'terminal',href:'/studio/tools'});
    if(inStudio&&state.editor)navs.unshift({title:'Save this draft',detail:'Ctrl / ⌘ S',icon:'check',action:'save'},{title:'Preview this story',detail:'See your words as readers will',icon:'eye',action:'preview'});
    const stories=(inStudio?state.posts:state.site?.posts||[]).map(p=>({userContent:true,title:p.title,detail:`${p.category||'Story'} · ${p.excerpt||p.slug}`,icon:'posts',href:inStudio?`/studio/posts/${url(p.id)}`:`/posts/${url(p.slug)}`}));
    const all=[...navs,...stories];
    modal('A shortcut to a good idea.',`<div class="palette-input">${icon('search',20)}<label class="sr-only" for="command-input">Search pages, stories, and actions</label><input id="command-input" placeholder="Where would you like to go?" role="combobox" aria-autocomplete="list" aria-expanded="true" aria-controls="command-results" autocomplete="off"></div><div id="command-results" role="listbox" aria-label="Commands and stories"></div><div class="palette-footer"><span>↑ ↓ to explore &nbsp; ↵ to open</span><span>esc to close</span></div>`,true);
    const input=$('#command-input');
    function draw(){const q=input.value.toLowerCase().trim();paletteItems=all.map((item,index)=>({...item,id:`command-${index}`,rank:!q?0:`${item.title} ${item.userContent?'':I18n.text(item.title)}`.toLowerCase().includes(q)?2:`${item.detail} ${item.userContent?'':I18n.text(item.detail)}`.toLowerCase().includes(q)?1:-1})).filter(x=>x.rank>=0).sort((a,b)=>b.rank-a.rank).slice(0,14);paletteSelection=0;$('#command-results').innerHTML=paletteItems.length?paletteItems.map((item,i)=>`<button class="command-option ${i===0?'selected':''}" id="${item.id}" role="option" aria-selected="${i===0}" data-command-index="${i}" tabindex="-1"><span class="command-icon">${icon(item.icon,17)}</span><span ${item.userContent?'data-no-i18n':''}><strong>${esc(item.title)}</strong><small>${esc(item.detail.slice(0,120))}</small></span>${icon('arrow',14)}</button>`).join(''):'<div class="palette-empty">No matching pages or stories. Try another word.</div>';updateSelection();}
    function updateSelection(){$$('[data-command-index]').forEach((el,i)=>{el.classList.toggle('selected',i===paletteSelection);el.setAttribute('aria-selected',String(i===paletteSelection));});if(paletteItems[paletteSelection])input.setAttribute('aria-activedescendant',paletteItems[paletteSelection].id);else input.removeAttribute('aria-activedescendant');}
    input.addEventListener('input',draw);input.addEventListener('keydown',e=>{if(e.isComposing)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(!paletteItems.length)return;paletteSelection=(paletteSelection+(e.key==='ArrowDown'?1:-1)+paletteItems.length)%paletteItems.length;updateSelection();$(`#${paletteItems[paletteSelection].id}`)?.scrollIntoView({block:'nearest'});}else if(e.key==='Enter'){e.preventDefault();runCommand(paletteSelection);}});const onLocale=()=>{if(input.isConnected)draw();else document.removeEventListener('folio:localechange',onLocale);};document.addEventListener('folio:localechange',onLocale);draw();input.focus();
  }
  async function runCommand(index){const item=paletteItems[index];if(!item)return;closeModal();if(item.href)await navigate(item.href);else await handleAction(item.action);}
  async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Copied to your clipboard.');}catch{modal('Copy this text.',`<div class="field"><textarea id="copy-fallback" rows="4" readonly>${esc(text)}</textarea></div><p>Your browser couldn’t copy automatically. Select the text and copy it.</p>`);$('#copy-fallback').select();}}
  function downloadJSON(data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const address=URL.createObjectURL(blob);const a=document.createElement('a');a.href=address;a.download=`folio-backup-${new Date().toISOString().slice(0,10)}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(address),1000);}
  async function handleAction(action){try{switch(action){case'command':commandPalette();break;case'close-modal':closeModal();break;case'mobile-nav':{const open=$('#mobile-nav').classList.toggle('hidden');$('[data-action="mobile-nav"]').setAttribute('aria-expanded',String(!open));break;}case'logout':if(state.dirty&&!confirm(I18n.text('Leave the studio and discard your unsaved changes?')))return;state.token='';state.info=null;sessionStorage.removeItem('folio.token');state.dirty=false;state.editor=null;await navigate('/studio');break;case'share':await copyText(location.href);break;case'capture':captureIdea();break;case'save':await saveDraft();break;case'preview':await previewEditor();break;case'publish':await reviewPublish();break;case'schedule':await reviewSchedule();break;case'submit-proposal':submitEditorProposal();break;case'migration-plan':await prepareMigration();break;case'migration-apply':confirmMigration();break;case'migration-export':await exportMigration();break;case'migration-reset':await resetMigration();break;case'migration-download-plan':downloadObject(migrationState().review,'folio-frozen-import-plan.json');break;case'migration-download-report':downloadObject(migrationState().report,'folio-import-report.json');break;case'delete':case'unpublish':await confirmPostAction(action);break;case'focus':{const on=document.body.classList.toggle('focus-mode');const b=$('[data-action="focus"]');if(b)b.innerHTML=`${icon('focus',13)} ${on?'Exit focus':'Focus'}`;break;}case'export-markdown':{const data=editorDataFromFields();if(!data)break;const blob=new Blob([data.markdown],{type:'text/markdown;charset=utf-8'});const address=URL.createObjectURL(blob);const a=document.createElement('a');a.href=address;a.download=`${data.slug||slugify(data.title)||'untitled'}.md`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(address),1000);toast('Markdown exported, including your current edits.');break;}case'export':{const data=await op('backup.export');downloadJSON(data);toast('Backup exported. Your words go with you.');break;}case'capabilities':{const detail=$('.tools-details');detail.open=true;detail.scrollIntoView({behavior:'smooth',block:'start'});break;}case'audit':{const data=await op('audit.list');const events=data.events||[];$('#audit-content').innerHTML=events.slice(0,50).map(e=>`<div class="audit-item"><strong data-no-i18n>${esc(e.operation)}</strong><span data-no-i18n>${esc(e.actor||'owner')} · ${esc(e.target||'instance')}</span><span>${date(e.at,false,true)}</span></div>`).join('')||'<p class="muted">No activity yet.</p>';break;}}}catch(err){toast(err.message,true);}}
  function insertMarkdown(kind){const t=$('#post-markdown');if(!t)return;if(state.viewMode!=='write'){$('#write-panel').classList.remove('hidden');$('#preview-panel').classList.add('hidden');state.viewMode='write';}const start=t.selectionStart,end=t.selectionEnd,selected=t.value.slice(start,end);const templates={bold:[`**${selected||I18n.t('format.bold')}**`,2],italic:[`*${selected||I18n.t('format.italic')}*`,1],heading:[`## ${selected||I18n.t('format.heading')}`,3],link:[`[${selected||I18n.t('format.link')}](https://)`,1],quote:[`> ${selected||I18n.t('format.quote')}`,2],list:[`- ${selected||I18n.t('format.list')}`,2],code:[selected.includes('\n')?`\n\x60\x60\x60\n${selected}\n\x60\x60\x60\n`:`\x60${selected||I18n.t('format.code')}\x60`,1]};const [replacement,offset]=templates[kind];t.setRangeText(replacement,start,end,'end');t.focus();if(!selected){t.selectionStart=start+offset;t.selectionEnd=start+replacement.length-offset;}t.dispatchEvent(new Event('input',{bubbles:true}));}
  function bindPage(){
    $('#migration-files')?.addEventListener('change',async e=>{try{await selectMigrationFiles(e.currentTarget);}catch(err){toast(err.message,true);e.target.value='';}});
    $('#migration-conflict')?.addEventListener('change',async e=>{const m=migrationState();if(m.locked)return;m.conflict=e.target.value;m.review=null;m.frozenPlanJSON=null;m.report=null;m.error='';await render();});
    $('#login-form')?.addEventListener('submit',async e=>{e.preventDefault();const button=$('#login-form button[type="submit"]');button.disabled=true;const candidate=$('#access-token').value.trim();const old=state.token;state.token=candidate;try{await op('posts.list');sessionStorage.setItem('folio.token',candidate);state.info=null;await render();}catch(err){state.token=old;$('#login-error').textContent=err.status===401?'That token didn’t open the studio. Check it and try again.':err.message;button.disabled=false;}});
    $('#public-search')?.addEventListener('submit',e=>{e.preventDefault();navigate(`/search?q=${url($('#search-query').value.trim())}`);});
    $('#studio-search')?.addEventListener('input',e=>{state.listQuery=e.target.value;$('#post-rows').innerHTML=postRows();});
    $('#markdown-import')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1024*1024)throw new Error('Choose a Markdown file smaller than 1 MB.');if($('#post-markdown').value.trim()&&!confirm(I18n.text('Replace the editor text with this Markdown file? Your current unsaved text will be replaced.')))return;const text=await file.text();$('#post-markdown').value=text;if(!state.editor.post.id&&!$('#post-title').value.trim()){const suggested=file.name.replace(/\.(md|markdown|txt)$/i,'').replace(/[-_]/g,' ').trim();$('#post-title').value=suggested||I18n.t('import.fallback');$('#post-title').dispatchEvent(new Event('input',{bubbles:true}));if(!$('#post-slug').value)$('#post-slug').value=slugify(suggested)||`imported-story-${Date.now()}`;}$('#post-markdown').dispatchEvent(new Event('input',{bubbles:true}));$('#write-panel').classList.remove('hidden');$('#preview-panel').classList.add('hidden');$$('[data-editor-mode]').forEach(b=>b.classList.toggle('active',b.dataset.editorMode==='write'));state.viewMode='write';$('#post-markdown').focus();toast('Markdown imported into your unsaved draft.');}catch(err){toast(err.message||'Could not read this file.',true);}finally{e.target.value='';}});
    $('#settings-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,button=f.querySelector('button[type="submit"]');button.disabled=true;$('#settings-error').textContent='';try{const settings=Object.fromEntries(new FormData(f));const data=await op('settings.update',{settings,expected_revision:state.settingsRevision,idempotency_key:crypto.randomUUID()});state.settingsRevision=data.revision;state.site=null;toast('Settings saved. Looking more like you.');}catch(err){$('#settings-error').textContent=err.message;}finally{button.disabled=false;}});
    $('#media-upload')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024){toast('Choose an image smaller than 5 MB.',true);e.target.value='';return;}const zone=$('.upload-zone');zone.style.opacity='.5';try{const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});await op('media.upload',{name:file.name,base64,idempotency_key:crypto.randomUUID()});toast('Image added to your library.');await render();}catch(err){toast(err.message||'Could not upload that image.',true);zone.style.opacity='1';e.target.value='';}});
    $('#restore-backup')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>64*1024*1024)throw new Error('The backup is too large (maximum 64 MB).');const backup=JSON.parse(await file.text());modal('Restore this backup?',`<p>This imports “${esc(file.name)}” into an empty FOLIO instance. The server verifies the checksum before importing. An instance with existing content cannot be restored over.</p><div class="error-notice">A backup may contain pending schedules. Due or overdue snapshots can publish after restore. Start the server with --pause-schedules first if you need time to review them.</div><div class="modal-actions"><button class="button secondary small" data-action="close-modal">Cancel</button><button class="button orange small" id="restore-confirm">Restore backup</button></div>`);$('#restore-confirm').onclick=async()=>{const b=$('#restore-confirm');b.disabled=true;try{await op('backup.restore',{backup,confirm:true,idempotency_key:crypto.randomUUID()});closeModal();state.site=null;toast('Backup restored. Welcome home.');await render();}catch(err){b.disabled=false;toast(err.message,true);}};}catch(err){toast(err instanceof SyntaxError?'This file is not valid JSON.':err.message,true);}finally{e.target.value='';}});
    if(state.editor&&$('#post-title')){const title=$('#post-title');const resize=()=>{title.style.height='auto';title.style.height=`${title.scrollHeight}px`;};resize();let autoSlug=!state.editor.post.id&&!state.editor.post.slug;$$('.editor-layout input,.editor-layout textarea').forEach(el=>el.addEventListener('input',()=>{markDirty();if(el.id==='post-title'){resize();if(autoSlug)$('#post-slug').value=slugify(el.value);}if(el.id==='post-slug')autoSlug=false;const markdown=$('#post-markdown').value;$('#word-count').textContent=`${words(markdown)} words · ${Math.max(1,Math.ceil(words(markdown)/210))} min read`;}));$('#post-markdown').addEventListener('keydown',e=>{if(e.isComposing)return;const t=e.currentTarget;if(e.key==='Tab'){e.preventDefault();t.setRangeText('  ',t.selectionStart,t.selectionEnd,'end');t.dispatchEvent(new Event('input',{bubbles:true}));}if(e.key==='Enter'&&!e.shiftKey&&t.selectionStart===t.selectionEnd){const pos=t.selectionStart;const before=t.value.slice(0,pos);const line=before.slice(before.lastIndexOf('\n')+1);const m=line.match(/^(\s*)([-*+] |\d+\. )((?:\[[ xX]\] )?)(.*)$/);if(m){e.preventDefault();if(!m[4].trim()){t.setRangeText('\n',pos-line.length,pos,'end');}else{const marker=/\d/.test(m[2])?`${parseInt(m[2],10)+1}. `:m[2];t.setRangeText(`\n${m[1]}${marker}${m[3]?'[ ] ':''}`,pos,pos,'end');}t.dispatchEvent(new Event('input',{bubbles:true}));}}});}
  }
  async function render(){const ticket=++state.render;const path=location.pathname.replace(/\/$/,'')||'/';document.body.classList.remove('focus-mode');document.documentElement.dataset.pageTitleKind='ui';document.title=I18n.text(`${state.site?.settings?.title||'FOLIO'} — An independent journal`);app.innerHTML=loading();try{await loadSite();if(ticket!==state.render)return;let html;if(path.startsWith('/studio')){document.title=I18n.t('document.studio');if(state.token&&!state.info)state.info=await op('system.info');if(!state.token)html=login();else if(path==='/studio'||path==='/studio/posts')html=await studioPosts();else if(path==='/studio/new')html=can('posts.create')?await editor(null):blockedWorkspace('posts');else if(path.startsWith('/studio/posts/'))html=await editor(decodeURIComponent(path.slice(14)));else if(path==='/studio/settings')html=can('settings.get')?await settingsPage():blockedWorkspace('settings');else if(path==='/studio/media')html=await mediaPage();else if(path==='/studio/tools')html=await toolsPage();else if(path==='/studio/proposals')html=await proposalsPage();else if(path.startsWith('/studio/proposals/'))html=await proposalsPage(decodeURIComponent(path.slice(18)));else if(path==='/studio/schedules')html=await schedulesPage();else if(path==='/studio/migration')html=await migrationPage();else html=studioShell('<div class="empty-state"><h2>This page wandered off.</h2><a class="button" href="/studio">Back to your writing</a></div>');}else{state.editor=null;state.dirty=false;if(path==='/')html=home();else if(path==='/topics')html=topics();else if(path.startsWith('/tag/'))html=tagPage(decodeURIComponent(path.slice(5)));else if(path==='/about')html=about();else if(path==='/search')html=await searchPage(new URLSearchParams(location.search).get('q')||'');else if(path.startsWith('/posts/'))html=await article(decodeURIComponent(path.slice(7)));else html=publicShell('<div class="empty-state"><h2>A page less traveled.</h2><p>This story may have moved, or hasn’t been published yet.</p><a class="button" href="/">Back to the journal</a></div>');}if(ticket!==state.render)return;app.innerHTML=html;I18n.apply(app);bindPage();}catch(err){if(ticket!==state.render)return;if(path.startsWith('/studio')&&err.status===401){state.token='';state.info=null;sessionStorage.removeItem('folio.token');app.innerHTML=login();I18n.apply(app);bindPage();toast('Your session needs a fresh access token.',true);}else{app.innerHTML=publicShell(`<div class="empty-state"><h2>${err.status===404?'This story isn’t here.':'A small interruption.'}</h2><p>${esc(err.message)}</p><a class="button secondary" href="/">Back to the journal</a><button class="button" style="margin-left:8px" id="retry-page">Try again</button></div>`);$('#retry-page').onclick=()=>render();}}}
  async function navigate(href){if(state.busy){toast('Finishing your save. Just a moment.');return;}const target=new URL(href,location.origin);if(state.dirty&&!confirm(I18n.text('Leave this story and discard your unsaved changes?')))return;state.dirty=false;closeModal(false);history.pushState({},'',target.pathname+target.search+target.hash);await render();window.scrollTo({top:0,behavior:'instant'});}
  document.addEventListener('click',async e=>{
    if(e.defaultPrevented)return;
    const action=e.target.closest('[data-action]');if(action){e.preventDefault();await handleAction(action.dataset.action);return;}
    const decision=e.target.closest('[data-proposal-decision]');if(decision){reviewProposalDecision(decision.dataset.proposalDecision);return;}
    const reschedule=e.target.closest('[data-schedule-reschedule]');if(reschedule){try{await reviewSchedule(reschedule.dataset.scheduleReschedule);}catch(err){toast(err.message,true);}return;}
    const cancel=e.target.closest('[data-schedule-cancel]');if(cancel){try{await cancelSchedule(cancel.dataset.scheduleCancel);}catch(err){toast(err.message,true);}return;}
    const category=e.target.closest('[data-category]');if(category){$$('[data-category]').forEach(b=>b.classList.toggle('active',b===category));const feature=state.site.posts.find(p=>p.featured)||state.site.posts[0];const rest=state.site.posts.filter(p=>p.id!==feature?.id);$('#home-post-grid').innerHTML=rest.filter(p=>!category.dataset.category||p.category===category.dataset.category).map(p=>postCard(p,rest.findIndex(x=>x.id===p.id)+1)).join('');return;}
    const filter=e.target.closest('[data-post-filter]');if(filter){state.listFilter=filter.dataset.postFilter;$$('[data-post-filter]').forEach(b=>b.classList.toggle('active',b===filter));$('#post-rows').innerHTML=postRows();return;}
    const copy=e.target.closest('[data-copy]');if(copy){await copyText(copy.dataset.copy);return;}
    const format=e.target.closest('[data-format]');if(format){insertMarkdown(format.dataset.format);return;}
    const mode=e.target.closest('[data-editor-mode]');if(mode){if(mode.dataset.editorMode==='preview')await handleAction('preview');else{$('#write-panel').classList.remove('hidden');$('#preview-panel').classList.add('hidden');$$('[data-editor-mode]').forEach(b=>b.classList.toggle('active',b===mode));state.viewMode='write';}return;}
    const restore=e.target.closest('[data-restore]');if(restore){const revision=Number(restore.dataset.restore),p=state.editor.post;modal(`Restore revision ${revision}?`,`<p>This creates a new draft from the historical revision. The live story stays unchanged.${state.dirty?' Your unsaved edits will be discarded.':''}</p><div class="modal-actions"><button class="button secondary small" data-action="close-modal">Cancel</button><button class="button orange small" id="confirm-revision">Restore draft</button></div>`);$('#confirm-revision').onclick=async()=>{const b=$('#confirm-revision');b.disabled=true;try{await op('posts.restore',{id:p.id,revision,expected_revision:p.revision,idempotency_key:crypto.randomUUID()});state.dirty=false;closeModal();toast(`Revision ${revision} restored as a new draft.`);await render();}catch(err){b.disabled=false;toast(err.message,true);}};return;}
    const command=e.target.closest('[data-command-index]');if(command){await runCommand(Number(command.dataset.commandIndex));return;}
    const link=e.target.closest('a[href]');
    if(!link||link.hasAttribute('download')||link.hasAttribute('data-native')||link.target||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||e.button!==0)return;
    const target=new URL(link.href,location.origin);
    // Blob URLs inherit this origin, but their downloads must stay browser-native.
    if(!['http:','https:'].includes(target.protocol)||target.origin!==location.origin||target.pathname.startsWith('/media/'))return;
    if(target.hash&&target.pathname===location.pathname)return;
    e.preventDefault();await navigate(target.href);
  });
  document.addEventListener('keydown',e=>{if(e.isComposing)return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if($('#command-input'))closeModal();else commandPalette();}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'&&state.editor&&location.pathname.startsWith('/studio')){e.preventDefault();handleAction('save');}if(e.key==='Escape'){if($('#modal-root').children.length){e.preventDefault();closeModal();}else if(document.body.classList.contains('focus-mode'))handleAction('focus');}if(e.key==='Tab'&&$('#modal-root').children.length){const focusable=$$('button:not(:disabled):not([tabindex="-1"]),a[href],input,textarea,select,[tabindex="0"]',$('#modal-root'));const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
  window.addEventListener('popstate',()=>{if(state.dirty){if(!confirm(I18n.text('Leave this story and discard your unsaved changes?'))){history.pushState({},'',state.editor?.post.id?`/studio/posts/${url(state.editor.post.id)}`:'/studio/new');return;}state.dirty=false;}closeModal(false);render();});
  window.addEventListener('beforeunload',e=>{if(state.dirty){e.preventDefault();e.returnValue='';}});
  render();
})();
